pub const MemoryBlock = struct {
    data: []u8,
    size: usize,
    capacity: usize,
    offset: usize,
    next: ?*MemoryBlock = null,
    prev: ?*MemoryBlock = null,
    id: u64,
    flags: u32,
    timestamp: u64,
    checksum: u32,
    ref_count: atomic.Value(usize),
    allocator: *Allocator,
    mutex: std.Thread.Mutex,
    padding: [56]u8,

    pub fn init(allocator: *Allocator, size: usize, id: u64) !*MemoryBlock {
        const aligned_size = math.alignForward(usize, size, @alignOf(usize));
        const block = try allocator.create(MemoryBlock);
        errdefer allocator.destroy(block);
        block.* = .{
            .data = &[_]u8{},
            .size = 0,
            .capacity = aligned_size,
            .offset = 0,
            .next = null,
            .prev = null,
            .id = id,
            .flags = 0,
            .timestamp = @as(u64, @intCast(time.nanoTimestamp())),
            .checksum = 0,
            .ref_count = atomic.Value(usize).init(1),
            .allocator = allocator,
            .mutex = .{},
            .padding = [_]u8{0} ** 56,
        };
        block.data = try allocator.alignedAlloc(u8, @alignOf(usize), aligned_size);
        block.updateChecksum();
        return block;
    }

    pub fn deinit(self: *MemoryBlock) void {
        if (self.ref_count.fetchSub(1, .acq_rel) == 1) {
            self.allocator.free(self.data);
            self.allocator.destroy(self);
        }
    }

    pub fn retain(self: *MemoryBlock) void {
        _ = self.ref_count.fetchAdd(1, .acq_rel);
    }

    pub fn release(self: *MemoryBlock) void {
        self.deinit();
    }

    pub fn resize(self: *MemoryBlock, new_size: usize) !void {
        const aligned_size = math.alignForward(usize, new_size, @alignOf(usize));
        if (aligned_size > self.capacity) {
            const new_data = try self.allocator.realloc(u8, self.data, aligned_size);
            self.data = new_data;
            self.capacity = aligned_size;
        }
        self.size = new_size;
        self.offset = 0;
        self.updateChecksum();
    }

    pub fn updateChecksum(self: *MemoryBlock) void {
        var hasher = std.hash.Crc32.init();
        if (self.size > 0) {
            hasher.update(self.data[0..self.size]);
        }
        self.checksum = hasher.final();
    }

    pub fn validate(self: *MemoryBlock) bool {
        var hasher = std.hash.Crc32.init();
        if (self.size > 0) {
            hasher.update(self.data[0..self.size]);
        }
        return hasher.final() == self.checksum;
    }

    pub fn copyFrom(self: *MemoryBlock, src: []const u8) !void {
        if (src.len > self.capacity) return error.Overflow;
        if (src.len > 0) {
            @memcpy(self.data[0..src.len], src);
        }
        self.size = src.len;
        self.updateChecksum();
    }

    pub fn copyTo(self: *MemoryBlock, dest: []u8) !void {
        if (dest.len < self.size) return error.Underflow;
        if (self.size > 0) {
            @memcpy(dest[0..self.size], self.data[0..self.size]);
        }
    }

    pub fn zero(self: *MemoryBlock) void {
        if (self.size > 0) {
            @memset(self.data[0..self.size], 0);
        }
        self.updateChecksum();
    }

    pub fn fill(self: *MemoryBlock, value: u8) void {
        if (self.size > 0) {
            @memset(self.data[0..self.size], value);
        }
        self.updateChecksum();
    }

    pub fn compare(self: *MemoryBlock, other: *const MemoryBlock) i32 {
        const min_size = @min(self.size, other.size);
        const ord = mem.order(u8, self.data[0..min_size], other.data[0..min_size]);
        return switch (ord) {
            .lt => -1,
            .eq => 0,
            .gt => 1,
        };
    }

    pub fn hash(self: *MemoryBlock) u64 {
        var hasher = std.hash.Wyhash.init(0);
        if (self.size > 0) {
            hasher.update(self.data[0..self.size]);
        }
        return hasher.final();
    }

    pub fn lock(self: *MemoryBlock) void {
        self.mutex.lock();
    }

    pub fn unlock(self: *MemoryBlock) void {
        self.mutex.unlock();
    }

    pub fn prefetch(self: *MemoryBlock, offset: usize, len: usize) void {
        if (offset >= self.size) return;
        const end = @min(self.size, offset + len);
        if (end <= offset) return;
        const ptr = self.data.ptr + offset;
        std.builtin.prefetch(ptr, .{ .rw = .read, .locality = 1, .cache = .data });
    }

    pub fn mlock(self: *MemoryBlock) !void {
        try std.posix.mlock(self.data);
    }

    pub fn munlock(self: *MemoryBlock) !void {
        try std.posix.munlock(self.data);
    }

    pub fn madvise(self: *MemoryBlock, advice: std.posix.Madvice) !void {
        if (self.size == 0) return;
        try std.posix.madvise(self.data.ptr, self.size, advice);
    }

    pub fn fsync(self: *MemoryBlock, fd: std.posix.fd_t) !void {
        if (self.flags & 1 == 0) return;
        try std.posix.fsync(fd);
    }

    pub fn serialize(self: *MemoryBlock) ![]u8 {
        const total = @sizeOf(u64) + self.size;
        var buffer = try self.allocator.alloc(u8, total);
        const size_bytes = buffer[0..@sizeOf(u64)];
        mem.writeInt(u64, size_bytes, self.size, .big);
        if (self.size > 0) {
            @memcpy(buffer[@sizeOf(u64)..total], self.data[0..self.size]);
        }
        return buffer;
    }

    pub fn deserialize(self: *MemoryBlock, data: []const u8) !void {
        if (data.len < @sizeOf(u64)) return error.InvalidFormat;
        const size = mem.readInt(u64, data[0..@sizeOf(u64)], .big);
        if (size > self.capacity) return error.Overflow;
        const usize_size: usize = @intCast(size);
        if (data.len < @sizeOf(u64) + usize_size) return error.InvalidFormat;
        if (usize_size > 0) {
            @memcpy(self.data[0..usize_size], data[@sizeOf(u64)..@sizeOf(u64) + usize_size]);
        }
        self.size = usize_size;
        self.updateChecksum();
    }

    pub fn snapshot(self: *MemoryBlock) !*MemoryBlock {
        const snap = try MemoryBlock.init(self.allocator, self.size, self.id + 1);
        if (self.size > 0) {
            try snap.copyFrom(self.data[0..self.size]);
        }
        return snap;
    }

    pub fn restore(self: *MemoryBlock, snap: *const MemoryBlock) !void {
        try self.resize(snap.size);
        if (snap.size > 0) {
            @memcpy(self.data[0..snap.size], snap.data[0..snap.size]);
        }
        self.updateChecksum();
    }

    pub fn checkpoint(self: *MemoryBlock) !*MemoryBlock {
        const checkpoint = try MemoryBlock.init(self.allocator, self.size, self.id);
        if (self.size > 0) {
            try checkpoint.copyFrom(self.data[0..self.size]);
        }
        checkpoint.prev = self.prev;
        checkpoint.next = self.next;
        self.prev = checkpoint;
        return checkpoint;
    }

    pub fn rollback(self: *MemoryBlock) !void {
        if (self.prev) |prev| {
            try self.restore(prev);
        }
    }

    pub fn shard(self: *MemoryBlock, shard_id: usize, total_shards: usize) !*MemoryBlock {
        if (total_shards == 0) return error.InvalidFormat;
        const base = self.size / total_shards;
        const rem = self.size % total_shards;
        const start = shard_id * base + @min(shard_id, rem);
        const len = base + (if (shard_id < rem) 1 else 0);
        if (start >= self.size) return error.InvalidFormat;
        const shard = try MemoryBlock.init(self.allocator, len, self.id * total_shards + shard_id);
        if (len > 0) {
            try shard.copyFrom(self.data[start..start + len]);
        }
        return shard;
    }

    pub fn audit(self: *MemoryBlock) !void {
        if (!self.validate()) return error.ChecksumMismatch;
    }

    pub fn backup(self: *MemoryBlock, path: []const u8) !void {
        const file = try std.fs.cwd().createFile(path, .{ .truncate = true });
        defer file.close();
        var header: [8]u8 = undefined;
        mem.writeInt(u64, header[0..], self.size, .little);
        try file.writeAll(&header);
        if (self.size > 0) {
            try file.writeAll(self.data[0..self.size]);
        }
    }

    pub fn restoreFrom(self: *MemoryBlock, path: []const u8) !void {
        const file = try std.fs.cwd().openFile(path, .{});
        defer file.close();
        var size_bytes: [8]u8 = undefined;
        try file.readNoEof(&size_bytes);
        const size_u64 = mem.readInt(u64, &size_bytes, .little);
        if (size_u64 > self.capacity) return error.Overflow;
        const size: usize = @intCast(size_u64);
        try self.resize(size);
        if (size > 0) {
            try file.readNoEof(self.data[0..size]);
        }
        self.updateChecksum();
    }

    pub fn profile(self: *MemoryBlock, start: u64) u64 {
        const end = @as(u64, @intCast(time.nanoTimestamp()));
        return end - start;
    }

    pub fn health(self: *MemoryBlock) bool {
        return self.validate() and self.ref_count.load(.acquire) > 0;
    }

    pub fn recycle(self: *MemoryBlock, max_recycle_size: usize) void {
        if (self.size <= max_recycle_size) {
            self.zero();
            self.ref_count.store(0, .release);
        }
    }
};

pub const MemoryArena = struct {
    blocks: ?*MemoryBlock = null,
    free_list: ?*MemoryBlock = null,
    allocator: *Allocator,
    config: MemoryConfig,
    total_allocated: atomic.Value(usize),
    total_freed: atomic.Value(usize),
    peak_usage: atomic.Value(usize),
    fragmentation: f64,
    stats: struct {
        alloc_count: atomic.Value(usize),
        free_count: atomic.Value(usize),
        resize_count: atomic.Value(usize),
        copy_count: atomic.Value(usize),
        compare_count: atomic.Value(usize),
        hash_count: atomic.Value(usize),
    },

    pub fn init(allocator: *Allocator, config: MemoryConfig) !*MemoryArena {
        const arena = try allocator.create(MemoryArena);
        arena.* = .{
            .blocks = null,
            .free_list = null,
            .allocator = allocator,
            .config = config,
            .total_allocated = atomic.Value(usize).init(0),
            .total_freed = atomic.Value(usize).init(0),
            .peak_usage = atomic.Value(usize).init(0),
            .fragmentation = 0.0,
            .stats = .{
                .alloc_count = atomic.Value(usize).init(0),
                .free_count = atomic.Value(usize).init(0),
                .resize_count = atomic.Value(usize).init(0),
                .copy_count = atomic.Value(usize).init(0),
                .compare_count = atomic.Value(usize).init(0),
                .hash_count = atomic.Value(usize).init(0),
            },
        };
        return arena;
    }

    pub fn deinit(self: *MemoryArena) void {
        var block = self.blocks;
        while (block) |b| {
            const next = b.next;
            b.ref_count.store(1, .release);
            b.deinit();
            block = next;
        }
        var free_block = self.free_list;
        while (free_block) |b| {
            const next_free = b.next;
            b.ref_count.store(1, .release);
            b.deinit();
            free_block = next_free;
        }
        self.allocator.destroy(self);
    }

    fn attachBlock(self: *MemoryArena, block: *MemoryBlock) void {
        block.next = self.blocks;
        if (self.blocks) |old| {
            old.prev = block;
        }
        block.prev = null;
        self.blocks = block;
    }

    pub fn alloc(self: *MemoryArena, size: usize) !*MemoryBlock {
        if (size == 0) return error.InvalidSize;
        if (size > self.config.max_alloc_size) return error.TooLarge;
        const aligned_size = math.alignForward(usize, size, self.config.alignment);

        var block: ?*MemoryBlock = null;
        var prev_free: ?*MemoryBlock = null;
        var cur_free = self.free_list;
        while (cur_free) |b| {
            if (b.capacity >= aligned_size) {
                block = b;
                const next_free = b.next;
                if (prev_free) |pf| {
                    pf.next = next_free;
                } else {
                    self.free_list = next_free;
                }
                b.next = null;
                break;
            }
            prev_free = cur_free;
            cur_free = b.next;
        }

        if (block == null) {
            const id = self.stats.alloc_count.fetchAdd(1, .acq_rel);
            block = try MemoryBlock.init(self.allocator, aligned_size, id);
            self.attachBlock(block.?);
        } else {
            try block.?.resize(aligned_size);
        }

        block.?.retain();
        self.total_allocated.fetchAdd(aligned_size, .acq_rel);
        const used = self.total_allocated.load(.acquire) - self.total_freed.load(.acquire);
        var peak = self.peak_usage.load(.acquire);
        while (used > peak) {
            const prev = self.peak_usage.compareExchangeWeak(peak, used, .acq_rel, .acquire) catch |e| {
                _ = e;
                peak = self.peak_usage.load(.acquire);
                continue;
            };
            if (prev == peak) break;
        }
        self.stats.alloc_count.fetchAdd(1, .acq_rel);
        return block.?;
    }

    pub fn free(self: *MemoryArena, block: *MemoryBlock) void {
        block.release();
        if (block.ref_count.load(.acquire) == 0) {
            const size = block.capacity;
            self.total_freed.fetchAdd(size, .acq_rel);
            block.next = self.free_list;
            self.free_list = block;
            self.stats.free_count.fetchAdd(1, .acq_rel);
            self.updateFragmentation();
        }
    }

    pub fn resize(self: *MemoryArena, block: *MemoryBlock, new_size: usize) !void {
        if (new_size == 0) {
            self.free(block);
            return;
        }
        try block.resize(new_size);
        self.stats.resize_count.fetchAdd(1, .acq_rel);
        self.updateFragmentation();
    }

    pub fn copy(self: *MemoryArena, src: *MemoryBlock, dest: *MemoryBlock) !void {
        try dest.copyFrom(src.data[0..src.size]);
        self.stats.copy_count.fetchAdd(1, .acq_rel);
    }

    pub fn compare(self: *MemoryArena, a: *MemoryBlock, b: *MemoryBlock) i32 {
        const cmp = a.compare(b);
        self.stats.compare_count.fetchAdd(1, .acq_rel);
        return cmp;
    }

    pub fn hash(self: *MemoryArena, block: *MemoryBlock) u64 {
        const h = block.hash();
        self.stats.hash_count.fetchAdd(1, .acq_rel);
        return h;
    }

    fn updateFragmentation(self: *MemoryArena) void {
        const total = self.total_allocated.load(.acquire);
        if (total == 0) {
            self.fragmentation = 0.0;
            return;
        }
        const used = total - self.total_freed.load(.acquire);
        const used_f: f64 = @floatFromInt(used);
        const total_f: f64 = @floatFromInt(total);
        self.fragmentation = 1.0 - used_f / total_f;
        if (self.fragmentation > self.config.max_fragmentation) {
            self.compact();
        }
    }

    fn compact(self: *MemoryArena) void {
        var block = self.blocks;
        while (block) |b| {
            if (b.size < b.capacity / 2) {
                b.resize(b.size) catch {};
            }
            block = b.next;
        }
    }

    pub fn getStats(self: *MemoryArena) struct {
        total_allocated: usize,
        total_freed: usize,
        peak_usage: usize,
        fragmentation: f64,
        alloc_count: usize,
        free_count: usize,
    } {
        return .{
            .total_allocated = self.total_allocated.load(.acquire),
            .total_freed = self.total_freed.load(.acquire),
            .peak_usage = self.peak_usage.load(.acquire),
            .fragmentation = self.fragmentation,
            .alloc_count = self.stats.alloc_count.load(.acquire),
            .free_count = self.stats.free_count.load(.acquire),
        };
    }

    pub fn resetStats(self: *MemoryArena) void {
        self.total_allocated.store(0, .release);
        self.total_freed.store(0, .release);
        self.peak_usage.store(0, .release);
        self.fragmentation = 0.0;
        self.stats.alloc_count.store(0, .release);
        self.stats.free_count.store(0, .release);
        self.stats.resize_count.store(0, .release);
        self.stats.copy_count.store(0, .release);
        self.stats.compare_count.store(0, .release);
        self.stats.hash_count.store(0, .release);
    }

    pub fn validateAll(self: *MemoryArena) bool {
        var valid = true;
        var block = self.blocks;
        while (block) |b| {
            if (!b.validate()) valid = false;
            block = b.next;
        }
        return valid;
    }

    pub fn compactAll(self: *MemoryArena) void {
        self.compact();
    }

    pub fn purgeAll(self: *MemoryArena) void {
        var block = self.blocks;
        while (block) |b| {
            const next = b.next;
            if (b.ref_count.load(.acquire) == 0) {
                self.free(b);
            }
            block = next;
        }
    }

    pub fn getBlockById(self: *MemoryArena, id: u64) ?*MemoryBlock {
        var block = self.blocks;
        while (block) |b| {
            if (b.id == id) return b;
            block = b.next;
        }
        return null;
    }

    pub fn insertBlock(self: *MemoryArena, block: *MemoryBlock) void {
        self.attachBlock(block);
    }

    pub fn removeBlock(self: *MemoryArena, block: *MemoryBlock) void {
        var cur = self.blocks;
        while (cur) |c| {
            if (c == block) {
                if (c.prev) |p| {
                    p.next = c.next;
                } else {
                    self.blocks = c.next;
                }
                if (c.next) |n| {
                    n.prev = c.prev;
                }
                break;
            }
            cur = c.next;
        }
    }

    pub fn iterateBlocks(self: *MemoryArena, comptime Visitor: type, visitor: Visitor) void {
        var block = self.blocks;
        while (block) |b| {
            if (!visitor.visit(b)) break;
            block = b.next;
        }
    }

    pub fn findBlocks(self: *MemoryArena, comptime Predicate: type, predicate: Predicate) ![]*MemoryBlock {
        var matches = ArrayList(*MemoryBlock).init(self.allocator.*);
        defer matches.deinit();
        var block = self.blocks;
        while (block) |b| {
            if (predicate.check(b)) try matches.append(b);
            block = b.next;
        }
        return matches.toOwnedSlice();
    }

    pub fn reduceBlocks(self: *MemoryArena, reducer: fn (u64, *MemoryBlock) u64, initial: u64) u64 {
        var result = initial;
        var block = self.blocks;
        while (block) |b| {
            result = reducer(result, b);
            block = b.next;
        }
        return result;
    }
};

pub const InteractionNet = struct {
    nodes: std.ArrayList(u8),
    edges: std.AutoHashMap(u32, u32),
    allocator: *Allocator,

    pub fn init(allocator: *Allocator) !InteractionNet {
        return .{
            .nodes = std.ArrayList(u8).init(allocator.*),
            .edges = std.AutoHashMap(u32, u32).init(allocator.*),
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *InteractionNet) void {
        self.nodes.deinit();
        self.edges.deinit();
    }

    pub fn addNode(self: *InteractionNet, value: u8) !usize {
        try self.nodes.append(value);
        return self.nodes.items.len - 1;
    }

    pub fn addEdge(self: *InteractionNet, from: u32, to: u32) !void {
        try self.edges.put(from, to);
    }

    pub fn evaluate(self: *InteractionNet) void {
        var i: usize = 0;
        while (i < self.nodes.items.len) : (i += 1) {
            const idx: u32 = @intCast(i);
            if (self.edges.get(idx)) |target| {
                const tgt_usize: usize = @intCast(target);
                if (tgt_usize < self.nodes.items.len) {
                    self.nodes.items[tgt_usize] = self.nodes.items[tgt_usize] + self.nodes.items[i];
                }
            }
        }
    }
};

pub fn propagate_diffusion(net: *InteractionNet) void {
    net.evaluate();
}

pub const WorkerContext = struct {
    net: *InteractionNet,
    start: usize,
    end: usize,
};

fn worker_proc(ctx: *WorkerContext) void {
    var i = ctx.start;
    while (i < ctx.end) : (i += 1) {
        ctx.net.evaluate();
    }
}

pub fn parallel_reason(net: *InteractionNet, steps: usize, num_workers: usize, allocator: Allocator) !void {
    if (num_workers == 0) return;
    var workers = try allocator.alloc(std.Thread, num_workers);
    defer allocator.free(workers);

    var contexts = try allocator.alloc(WorkerContext, num_workers);
    defer allocator.free(contexts);

    const chunk_size = if (steps == 0) 0 else (steps + num_workers - 1) / num_workers;

    var w: usize = 0;
    while (w < num_workers) : (w += 1) {
        const start = w * chunk_size;
        const end = @min(steps, (w + 1) * chunk_size);
        contexts[w] = WorkerContext{
            .net = net,
            .start = start,
            .end = end,
        };
        workers[w] = try std.Thread.spawn(.{}, worker_proc, .{&contexts[w]});
    }
    w = 0;
    while (w < num_workers) : (w += 1) {
        workers[w].join();
    }
}

const BENCH_ITERATIONS_MEMORY = 1000;
const TENSOR_SIZE_MEMORY = 1024 * 1024;

pub const Shape = []const usize;

pub const Tensor = struct {
    data: []f64,
    shape: Shape,
    allocator: Allocator,

    pub fn init(allocator: Allocator, shape: Shape) !Tensor {
        var size: usize = 1;
        for (shape) |dim| {
            if (dim == 0) return error.InvalidFormat;
            size *= dim;
        }
        var data = try allocator.alloc(f64, size);
        @memset(data, 0.0);
        const shape_copy = try allocator.dupe(usize, shape);
        return .{
            .data = data,
            .shape = shape_copy,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *Tensor) void {
        self.allocator.free(self.data);
        self.allocator.free(self.shape);
    }

    pub fn copy(self: *Tensor, allocator: Allocator) !Tensor {
        var new_data = try allocator.alloc(f64, self.data.len);
        if (self.data.len > 0) {
            @memcpy(new_data, self.data);
        }
        const shape_copy = try allocator.dupe(usize, self.shape);
        return .{
            .data = new_data,
            .shape = shape_copy,
            .allocator = allocator,
        };
    }

    pub fn add(self: *Tensor, other: *const Tensor) !Tensor {
        if (!mem.eql(usize, self.shape, other.shape)) return error.ShapeMismatch;
        var result = try Tensor.init(self.allocator, self.shape);
        var i: usize = 0;
        while (i < self.data.len) : (i += 1) {
            result.data[i] = self.data[i] + other.data[i];
        }
        return result;
    }

    pub fn mul(self: *Tensor, other: *const Tensor) !Tensor {
        if (!mem.eql(usize, self.shape, other.shape)) return error.ShapeMismatch;
        var result = try Tensor.init(self.allocator, self.shape);
        var i: usize = 0;
        while (i < self.data.len) : (i += 1) {
            result.data[i] = self.data[i] * other.data[i];
        }
        return result;
    }
};

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    std.log.info("Memory Benchmark - JAIDE v1", .{});
    std.log.info("Iterations: {d}", .{BENCH_ITERATIONS_MEMORY});
    std.log.info("Tensor size: {d} elements", .{TENSOR_SIZE_MEMORY});

    var total_alloc_time: u64 = 0;
    var total_dealloc_time: u64 = 0;
    var total_copy_time: u64 = 0;

    var i: usize = 0;
    while (i < BENCH_ITERATIONS_MEMORY) : (i += 1) {
        const start_alloc = @as(u64, @intCast(std.time.nanoTimestamp()));
        var tensor = try Tensor.init(allocator, &[_]usize{TENSOR_SIZE_MEMORY});
        const end_alloc = @as(u64, @intCast(std.time.nanoTimestamp()));
        total_alloc_time += end_alloc - start_alloc;

        const start_copy = @as(u64, @intCast(std.time.nanoTimestamp()));
        var copy_tensor = try tensor.copy(allocator);
        const end_copy = @as(u64, @intCast(std.time.nanoTimestamp()));
        total_copy_time += end_copy - start_copy;

        copy_tensor.deinit();

        const start_dealloc = @as(u64, @intCast(std.time.nanoTimestamp()));
        tensor.deinit();
        const end_dealloc = @as(u64, @intCast(std.time.nanoTimestamp()));
        total_dealloc_time += end_dealloc - start_dealloc;
    }

    const avg_alloc_ns = @as(f64, @floatFromInt(total_alloc_time)) / @as(f64, @floatFromInt(BENCH_ITERATIONS_MEMORY));
    const avg_dealloc_ns = @as(f64, @floatFromInt(total_dealloc_time)) / @as(f64, @floatFromInt(BENCH_ITERATIONS_MEMORY));
    const avg_copy_ns = @as(f64, @floatFromInt(total_copy_time)) / @as(f64, @floatFromInt(BENCH_ITERATIONS_MEMORY));

    std.log.info("Average allocation time: {d:.2} ns", .{avg_alloc_ns});
    std.log.info("Average deallocation time: {d:.2} ns", .{avg_dealloc_ns});
    std.log.info("Average copy time: {d:.2} ns", .{avg_copy_ns});
}
